import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        long n = in.nextLong();
        long a = 0;
        while (a * a < n) a++;
        long b = 0;
        while (b * b < a * a - n) b++;
        System.out.println((a + b) + " " + (a - b));
    }
}

